type registerRequest struct {
	Code     string `json:"code"`
	DeviceID string `json:"device_id"`
}

type registerResponse struct {
	Token     string `json:"token"`
	DeviceID  string `json:"device_id"`
	ExpiresAt int64  `json:"expires_at"`
}

// handleRegister 激活码注册 + 设备绑定
func handleRegister(store *Store, w http.ResponseWriter, r *http.Request) {
	// 限流：每 IP 10 次/分
	if !registerLimiter.allow(clientIP(r)) {
		writeJSON(w, http.StatusTooManyRequests, map[string]string{"error": "请求过于频繁"})
		return
	}
	var req registerRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "无效请求"})
		return
	}
	if req.Code == "" || req.DeviceID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "缺少 code 或 device_id"})
