// requireAuth 校验 token + 签名，返回设备
func requireAuth(store *Store, next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token := r.Header.Get("X-Token")
		if token == "" {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "未授权"})
			return
		}
		dev, err := store.GetDeviceByTokenHash(hashToken(token))
		if err != nil {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "token 无效"})
			return
		}
		// 校验激活码仍有效
		code, err := store.GetCode(dev.Code)
		if err != nil || !code.IsValid() {
			writeJSON(w, http.StatusForbidden, map[string]string{"error": "授权已过期"})
			return
		}
		// 校验签名
		ok, msg := verifySignature(r, token)
		if !ok {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": msg})
			return
		}
		// 限流：每设备 30 次/分
		if !parseLimiter.allow("dev:"+dev.DeviceID) {
			writeJSON(w, http.StatusTooManyRequests, map[string]string{"error": "请求过于频繁"})
			return
		}
		store.TouchDevice(dev.DeviceID, dev.Code)
		next(w, r)
	}
}
