// HMAC 签名校验 + 防重放（时间戳窗口 + nonce 一次性）
package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

const maxTimestampSkew = 5 * 60 // 时间戳允许偏差：5 分钟

// nonceStore 防重放：记录已用过的 nonce，超过 TTL 自动清理
type nonceStore struct {
	mu   sync.Mutex
	seen map[string]time.Time
	ttl  time.Duration
}

func newNonceStore(ttl time.Duration) *nonceStore {
	ns := &nonceStore{seen: map[string]time.Time{}, ttl: ttl}
	go func() {
		ticker := time.NewTicker(ttl / 2)
		defer ticker.Stop()
		for range ticker.C {
			ns.cleanup()
		}
	}()
	return ns
}

func (ns *nonceStore) checkAndSet(nonce string) bool {
	ns.mu.Lock()
	defer ns.mu.Unlock()
	if _, ok := ns.seen[nonce]; ok {
		return false // 已用过 = 重放
	}
	ns.seen[nonce] = time.Now()
	return true
}

func (ns *nonceStore) cleanup() {
	ns.mu.Lock()
	defer ns.mu.Unlock()
	cutoff := time.Now().Add(-ns.ttl)
	for k, v := range ns.seen {
		if v.Before(cutoff) {
			delete(ns.seen, k)
		}
	}
}

// verifySignature 校验请求签名。
// 客户端签名内容：HMAC-SHA256(key=token, msg=method\npath\ntimestamp\nnonce\nbodySHA256)
// 签名正确且时间戳在窗口内且 nonce 未被用过 → 通过。
// 校验通过后恢复 r.Body（后续 handler 仍需读取）。
func verifySignature(r *http.Request, token string) (bool, string) {
	ts := r.Header.Get("X-Timestamp")
	nonce := r.Header.Get("X-Nonce")
	sign := r.Header.Get("X-Sign")
	if ts == "" || nonce == "" || sign == "" {
		return false, "缺少签名头 (X-Timestamp/X-Nonce/X-Sign)"
	}

	// 1. 时间戳窗口
	t, err := strconv.ParseInt(ts, 10, 64)
	if err != nil {
		return false, "时间戳非法"
	}
	now := time.Now().Unix()
	if now-t > maxTimestampSkew || t-now > maxTimestampSkew {
		return false, "时间戳超出窗口"
	}

	// 2. 防重放
	if !globalNonceStore.checkAndSet(nonce) {
		return false, "重放请求"
	}

	// 3. 签名校验
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return false, "读取请求体失败"
	}
	r.Body = io.NopCloser(strings.NewReader(string(body)))
	bodyHash := sha256.Sum256(body)
	msg := fmt.Sprintf("%s\n%s\n%s\n%s\n%s", r.Method, r.URL.Path, ts, nonce, hex.EncodeToString(bodyHash[:]))
	mac := hmac.New(sha256.New, []byte(token))
	mac.Write([]byte(msg))
	expected := hex.EncodeToString(mac.Sum(nil))
	if !hmac.Equal([]byte(expected), []byte(sign)) {
		return false, "签名不匹配"
	}
	return true, ""
}

// 内存限流器：滑动窗口，按 key（设备/IP）计数
package main

import (
	"sync"
	"time"
)

type rateLimiter struct {
	mu       sync.Mutex
	buckets  map[string]*bucket
	limit    int           // 窗口内允许的最大次数
	window   time.Duration // 窗口时长
}

type bucket struct {
	count     int
	windowEnd time.Time
}

func newRateLimiter(limit int, window time.Duration) *rateLimiter {
	rl := &rateLimiter{
		buckets: map[string]*bucket{},
		limit:   limit,
		window:  window,
	}
	go rl.cleanupLoop()
	return rl
}

// Allow 判断 key 是否允许通过本次请求
func (rl *rateLimiter) Allow(key string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	now := time.Now()
	b, ok := rl.buckets[key]
	if !ok || now.After(b.windowEnd) {
		rl.buckets[key] = &bucket{count: 1, windowEnd: now.Add(rl.window)}
		return true
	}
	b.count++
	return b.count <= rl.limit
}

func (rl *rateLimiter) cleanupLoop() {
	ticker := time.NewTicker(rl.window)
	defer ticker.Stop()
	for range ticker.C {
		rl.mu.Lock()
		now := time.Now()
		for k, v := range rl.buckets {
			if now.After(v.windowEnd) {
				delete(rl.buckets, k)
			}
		}
		rl.mu.Unlock()
	}
}

// 激活码注册 + 设备绑定 + token 颁发
package main

import (
	"encoding/json"
	"net/http"
