// handleAdminList 管理接口：查看激活码与绑定设备（需 X-Admin-Key 头）
func handleAdminList(store *Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if !checkAdminKey(r) {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "管理密钥错误"})
			return
		}
		rows, err := store.db.Query(`SELECT code, status, expires_at, created_at, note FROM activation_codes ORDER BY created_at DESC LIMIT 200`)
		if err != nil {
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "查询失败"})
			return
		}
		defer rows.Close()

		type codeRow struct {
			Code      string `json:"code"`
			Status    string `json:"status"`
			ExpiresAt int64  `json:"expires_at"`
			CreatedAt int64  `json:"created_at"`
			Note      string `json:"note"`
			Devices   int    `json:"devices"`
		}
		codes := []codeRow{}
		for rows.Next() {
			var c codeRow
			if err := rows.Scan(&c.Code, &c.Status, &c.ExpiresAt, &c.CreatedAt, &c.Note); err != nil {
				continue
			}
			c.Devices, _ = store.CountDevices(c.Code)
			codes = append(codes, c)
		}
