// 抖音直播录制 SaaS 服务端（版本3）
// 职责：激活码/设备授权 + HMAC 签名校验 + 限流 + 流地址解析（解析复用 internal/extractor）
// 录制本身在客户端完成，服务器只做轻活，避免带宽成本。
package main

import (
	"crypto/subtle"
	"encoding/json"
	"log"
	"net"
	"net/http"
	"os"
	"strings"
	"time"

	"douyin-recorder-wails/internal/extractor"
